'use strict';
(()=>{
const events=[];const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const safe=s=>String(s||'').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,48);
const campaign=new URLSearchParams(location.search);
function track(name,props={}){const allowed=['page','concept_id','selected_offer_id','scenario_id','demo_source_id','reason_category','price_version','displayed_price_id','currency','qualification_version','verified'];const cleaned=Object.fromEntries(Object.entries(props).filter(([k,v])=>allowed.includes(k)&&['string','number','boolean'].includes(typeof v)));events.push({event:name,...cleaned,utm_source:safe(campaign.get('utm_source')),utm_campaign:safe(campaign.get('utm_campaign'))});if(events.length>60)events.shift();const list=$('#event-list');if(list){list.replaceChildren(...events.map(x=>{const li=document.createElement('li');li.textContent=JSON.stringify(x);return li;}));}}
window.SRPreview={track,events,modal:(title,content)=>{const dialog=$('#info-dialog');$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;dialog.showModal();}};
track('landing_view',{page:document.body.dataset.page});
$$('[data-offer]').forEach(a=>a.addEventListener('click',()=>track('offer_15_selected',{concept_id:15,selected_offer_id:Number(a.dataset.offer),page:document.body.dataset.page})));
const menus=$$('[data-menu]');function closeMenus(){menus.forEach(b=>{b.setAttribute('aria-expanded','false');$('#menu-'+b.dataset.menu).hidden=true;});}
menus.forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';closeMenus();b.setAttribute('aria-expanded',String(open));$('#menu-'+b.dataset.menu).hidden=!open;}));
document.addEventListener('click',ev=>{if(!ev.target.closest('.site-nav'))closeMenus();});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){const expanded=menus.find(b=>b.getAttribute('aria-expanded')==='true');closeMenus();if(expanded)expanded.focus();const toggle=$('.mobile-toggle');if(toggle?.getAttribute('aria-expanded')==='true'){toggle.click();toggle.focus();}}});
const mobile=$('.mobile-toggle');mobile?.addEventListener('click',()=>{const open=mobile.getAttribute('aria-expanded')!=='true';mobile.setAttribute('aria-expanded',String(open));mobile.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#mobile-nav').hidden=!open;document.body.classList.toggle('menu-open',open);});
document.addEventListener('keydown',ev=>{if(ev.key!=='Tab'||mobile?.getAttribute('aria-expanded')!=='true')return;const focusable=[mobile,...$('#mobile-nav').querySelectorAll('a')];const first=focusable[0],last=focusable[focusable.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}});
// Reversible, staggered entrances without scroll hijacking or hidden content.
if(document.body.dataset.page!=='workbench' && 'IntersectionObserver' in window){
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
 const selector=['.section-heading','.chapter-split > div','.evidence-layout > div','.editorial-module-layout > aside','.editorial-module-list > a','.module-index > a','.numbered-steps > article','.gate-grid > article','.pricing-grid > article','.faq-list > details','.control-list > li','.io-ledger > div','.policy-ledger > div','.calculation-ledger > div','.guide-shelf > a','.transcript-public > article','.closing-cta .container > div'].join(',');
 const targets=$$('main '+selector.split(',').join(',main ')).filter(el=>!el.parentElement.closest(selector));
 const groups=new Map();
 targets.forEach(el=>{const group=el.closest('section')||el.parentElement;const n=groups.get(group)||0;groups.set(group,n+1);el.classList.add('scroll-reveal');el.style.setProperty('--reveal-x',n%2?'42px':'-42px');el.style.setProperty('--reveal-delay',Math.min(n%5*90,360)+'ms');});
 const entrances=new IntersectionObserver(entries=>{entries.forEach(({target,isIntersecting})=>{target.classList.toggle('scroll-in-view',isIntersecting&&!reduce.matches&&!document.body.classList.contains('motion-paused'));});},{threshold:0,rootMargin:'-24px 0px -24px 0px'});
 targets.forEach(el=>entrances.observe(el));
 reduce.addEventListener('change',()=>{targets.forEach(el=>el.classList.remove('scroll-in-view'));if(!reduce.matches)targets.forEach(el=>{entrances.unobserve(el);entrances.observe(el);});});
}
const motion=new IntersectionObserver(es=>es.forEach(x=>x.target.classList.toggle('motion-offscreen',!x.isIntersecting)),{threshold:.12});$$('[data-motion]').forEach(el=>motion.observe(el));
$$('.motion-toggle').forEach(b=>b.addEventListener('click',()=>{const paused=document.body.classList.toggle('motion-paused');$$('.motion-toggle').forEach(x=>{x.setAttribute('aria-pressed',String(paused));x.firstChild.textContent=paused?'Resume motion ':'Pause motion ';});}));
$$('.motion-replay').forEach(b=>b.addEventListener('click',()=>{$$('[data-motion]').forEach(x=>{motion.unobserve(x);const next=x.cloneNode(true);x.replaceWith(next);motion.observe(next);});}));
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));
const prices=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){track('price_view',{price_version:'hypothesis-v1',displayed_price_id:'category-pilot-2500',currency:'USD'});prices.unobserve(x.target);}}),{threshold:.3});$$('[data-price]').forEach(x=>prices.observe(x));
$$('[data-profile]').forEach(b=>b.addEventListener('click',()=>window.SRPreview.modal(b.dataset.profile+' profile', '<p>No verified SourcingRecord '+b.dataset.profile+' company profile URL has been supplied. This footer uses the brand mark as a labeled preview.</p><p>No profile or endorsement is claimed.</p>')));
$('[data-close-dialog]').addEventListener('click',()=>$('#info-dialog').close());$('#info-dialog').addEventListener('click',ev=>{if(ev.target===$('#info-dialog'))$('#info-dialog').close();});
$('.event-inspector-toggle').addEventListener('click',()=>{const open=$('#event-inspector').hidden;$('#event-inspector').hidden=!open;$('.event-inspector-toggle').setAttribute('aria-expanded',String(open));});$('[data-close-events]').addEventListener('click',()=>{$('#event-inspector').hidden=true;$('.event-inspector-toggle').setAttribute('aria-expanded','false');$('.event-inspector-toggle').focus();});
function download(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$$('[data-inquiry]').forEach(form=>{let summary=null;const offer=Number(campaign.get('offer'));if(offer>=1&&offer<=5)form.elements.selected_offer_id.value=String(offer);const controls=[...form.querySelectorAll('[required]')];
const validate=c=>{const valid=c.type==='checkbox'?c.checked:!!c.value.trim()&&(c.type!=='email'||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.value));c.setAttribute('aria-invalid',String(!valid));const holder=c.closest('.field,.consent-field');let msg=holder.querySelector('.field-error');msg.textContent=valid?'':c.type==='checkbox'?'Acknowledge the local preview before preparing a summary.':c.type==='email'?'Enter a valid work email.':'Complete this field.';msg.id='error-'+(c.id||c.name);c.setAttribute('aria-describedby',msg.id);return valid;};
form.addEventListener('submit',ev=>{ev.preventDefault();const errors=controls.filter(c=>!validate(c));if(errors.length){form.querySelector('.form-status').textContent='Please check the highlighted fields. Nothing was submitted.';errors[0].focus();return;}const fd=new FormData(form);summary={preview:true,submitted:false,kind:form.dataset.inquiry,work_email:fd.get('work_email'),company:fd.get('company'),role:fd.get('role'),category:fd.get('category'),selected_offer_id:Number(fd.get('selected_offer_id')),repeat_frequency_band:fd.get('repeat_frequency_band'),named_owner_status:fd.get('named_owner_status'),current_tool:fd.get('current_tool'),preview_acknowledged:true,marketing_interest_indicated:fd.has('marketing_opt_in'),privacy_version:'concept-preview-v1'};const dl=form.querySelector('.inquiry-summary dl');dl.replaceChildren();for(const [key,value] of Object.entries(summary)){if(['work_email','company','role','category','selected_offer_id','current_tool'].includes(key)){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key.replaceAll('_',' ');dd.textContent=String(value);dl.append(dt,dd);}}form.querySelector('.inquiry-summary').hidden=false;form.querySelector('.form-status').textContent='Preview summary prepared locally. Nothing was submitted.';});
controls.forEach(c=>c.addEventListener('input',()=>{if(c.getAttribute('aria-invalid')==='true')validate(c);}));form.querySelector('[data-download-inquiry]').addEventListener('click',()=>{if(summary)download(summary,'SourcingRecord-preview-inquiry.json');});form.querySelector('[data-clear-inquiry]').addEventListener('click',()=>{form.reset();summary=null;form.querySelector('.inquiry-summary').hidden=true;form.querySelector('.form-status').textContent='Form cleared. No inquiry was submitted.';controls.forEach(c=>c.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(x=>x.textContent='');form.querySelector('input').focus();});});
})();
